    input_records = []

    for node in nodes:
        if node['kind'] == 'table':
            cols = node['columns']
            rows = table_rows(node)
            # Identify year columns
            year_cols = []
            for i, col in enumerate(cols):
                y = get_year(col)
                if y:
                    year_cols.append((i, y))

            for idx, row in rows:
                label = row.get('col0') or list(row.values())[0]
                if not label: continue

                # Heuristics for input (start of period, opening balance, given constant)
                is_input = any(keyword in label.lower() for keyword in ["opening", "beginning", "outstanding at", "initial"])

                if is_input:
                    for col_idx, year in year_cols:
                        val_str = row.get(cols[col_idx]) if cols[col_idx] else (list(row.values())[col_idx] if col_idx < len(row) else None)
                        val = clean_num(val_str)
                        if val is not None:
                            input_records.append({
                                "id": f"in_{node['node_id']}_{idx}_{year}",
                                "time": year,
                                "kind": "state",
                                "entities": [label],
                                "fields": {label: val},
                                "src": [node['node_id'], idx]
                            })
    return input_records

