    for node in nodes:
        if node['kind'] == 'list':
            for line in node.get('lines', []):
                # Look for "limit of X", "capacity is Y", "rate of Z"
                match = re.search(r'(\w+)\s+(?:is|of|at)\s+([$\d.,]+)', line, re.I)
