            # Same logic for text nodes
            match = re.search(r'(\w+)\s+(?:is|of|at)\s+([$\d.,]+)', node.get('text', ''), re.I)
            if match:
                name, val_str = match.groups()
                val = clean_num(val_str)
                if val is not None:
                    params_dict[name] = val

    return params_dict

