import re

def get_year(text):
    """Extracts the first 4-digit year from text."""
    if not text:
        return None
    matches = re.findall(r'\b(19|20)\d{2}\b', text)
    return float(matches[0]) if matches else None

def clean_num(text):
    """Cleans financial strings into floats."""
    if text is None:
        return None
    s = text.strip()
    if s in ('—', '–', '', 'None', 'null', 'n/a', 'N/A'):
        return None
    # Remove currency symbols and commas
    s = re.sub(r'[$\s,€]', '', s)
    # Handle parentheses for negative numbers
    if s.startswith('(') and s.endswith(')'):
        s = '-' + s[1:-1]
    try:
        return float(s)
    except ValueError:
        return None

def get_time_cols(node):
    """Identifies columns containing years, sorting them ascendingly."""
    cols = node.get('columns', [])
    time_cols = []
    # 1. Check column names
    for col in cols:
        y = get_year(col)
        if y:
            time_cols.append((col, y))

    # 2. If no years in column names, check the first row for date markers
    if not time_cols:
        for idx, row in table_rows(node):
            if idx == 0:
                for col_name, cell in row.items():
                    y = get_year(cell)
                    if y:
                        time_cols.append((col_name, y))
                break

    # Sort by year ascendingly
    time_cols.sort(key=lambda x: x[1])
    return time_cols

def entities(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    nodes = scope_nodes(doc, scope_node)
    ents = set()
    for node in nodes:
        if node['kind'] == 'table':
            cols = node.get('columns', [])
            if not cols: continue
            label_col = cols[0]
            for idx, row in table_rows(node):
                label = row.get(label_col)
                if label and label.strip():
                    l_strip = label.strip().lower()
                    # Exclude headers and unit rows
                    if not (l_strip.startswith('(in') or l_strip.startswith('year') or l_strip.startswith('fiscal')):
                        ents.add(label.strip())
    return [{"id": e, "description": e} for e in ents]

def recorded_end(doc, scope) -> float or None:
    scope_node = node_by_title(doc, scope)
    nodes = scope_nodes(doc, scope_node)
    years = []
    for node in nodes:
        if node['kind'] == 'table':
            for col in node.get('columns', []):
                y = get_year(col)
                if y: years.append(y)
            for idx, row in table_rows(node):
                for cell in row.values():
                    y = get_year(cell)
                    if y: years.append(y)
        elif node['kind'] == 'list':
            for line in node.get('lines', []):
                matches = re.findall(r'\b(19|20)\d{2}\b', line)
                years.extend([float(m) for m in matches])
        elif node['kind'] == 'text':
            matches = re.findall(r'\b(19|20)\d{2}\b', node.get('text', ''))
            years.extend([float(m) for m in matches])
    return max(years) if years else None

def inputs(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    nodes = scope_nodes(doc, scope_node)
    input_records = []

    for node in nodes:
        if node['kind'] == 'table':
            cols = node.get('columns', [])
            if not cols: continue

            time_cols = get_time_cols(node)
            if not time_cols: continue

            # Check if years were found in the first row
            time_in_row_0 = False
            for col in cols:
                if get_year(col):
                    time_in_row_0 = False
                    break
            else:
                for idx, row in table_rows(node):
                    if idx == 0:
                        for cell in row.values():
                            if get_year(cell):
                                time_in_row_0 = True
                                break
                        break

            start_row = 1 if time_in_row_0 else 0
            label_col = cols[0]

            for idx, row in table_rows(node):
                if idx < start_row: continue
                label = row.get(label_col)
                if not label or not label.strip(): continue
                l_strip = label.strip().lower()
                if l_strip.startswith('(in') or l_strip.startswith('year') or l_strip.startswith('fiscal'):
                    continue

                # Labels implying a starting state are treated as inputs for the earliest year
